function isRecoveryRetryDue(task: Pick<Task, "nextRecoveryAt">, now: number): boolean {
  if (!task.nextRecoveryAt) return true;
  const retryAt = Date.parse(task.nextRecoveryAt);
  return !Number.isFinite(retryAt) || retryAt <= now;
}

